if (input.headers) {
  // Webhook source
  const body = input.body || {};
  return [{ json: { topic: body.topic || null, pillar: body.pillar || null, source: 'webhook' } }];
} else {
  // Schedule source
  return [{ json: { topic: null, pillar: null, source: 'schedule' } }];
}

const apiKey = 'b183c082b67f0971673dbab7ce0a14883f75e5012d09720d17c540efce67bc39';

const aiQuery = encodeURIComponent('"AI agents" OR "Claude AI" OR "AI automation" news today');
const mktQuery = encodeURIComponent('"UGC ads" OR "AI marketing" OR "AI ads" latest');

const [aiResp, mktResp] = await Promise.all([
  this.helpers.httpRequest({
    method: 'GET',
    url: 'https://serpapi.com/search.json?engine=google&q=' + aiQuery + '&num=5&api_key=' + apiKey,
    json: true
  }),
  this.helpers.httpRequest({
    method: 'GET',
    url: 'https://serpapi.com/search.json?engine=google&q=' + mktQuery + '&num=5&api_key=' + apiKey,
    json: true
  })
]);

const results = [];

const aiOrganic = (aiResp.organic_results || []).slice(0, 4);
for (const r of aiOrganic) {
  results.push({ title: r.title || '', snippet: r.snippet || '', link: r.link || '' });
}

const aiVideos = (aiResp.inline_videos || []).slice(0, 2);
for (const v of aiVideos) {
  results.push({ title: v.title || '', snippet: v.channel || '', link: v.link || '' });
}

const mktOrganic = (mktResp.organic_results || []).slice(0, 3);
for (const r of mktOrganic) {
  results.push({ title: r.title || '', snippet: r.snippet || '', link: r.link || '' });
}

return [{ json: { ai_news: results.slice(0, 8) } }];

const topPostsData = $('Fetch Top Posts').first().json;
const learningsData = $('Fetch Brand Learnings').first().json;
const eventsData = $('Fetch Recent Events').first().json;
const newsData = $('Scan AI News').first().json;
const sysLearningsData = $('Fetch System Learnings').first().json;
const defaults = $('Set Defaults').first().json;

const topPosts = (topPostsData.records || []).map(r => ({
  pillar: r.fields.content_pillar,
  format: r.fields.post_format,
  text: r.fields.draft_text,
  likes: r.fields.likes || 0,
  comments: r.fields.comments_count || 0,
  impressions: r.fields.impressions || 0
}));

const learnings = (learningsData.records || []).map(r => ({
  category: r.fields.category,
  insight: r.fields.insight
}));

const events = (eventsData.records || []).map(r => ({
  agent: r.fields.agent,
  event_type: r.fields.event_type,
  details: r.fields.details,
  created_at: r.fields.created_at
}));

const aiNews = newsData.ai_news || [];

const systemLearnings = (sysLearningsData.records || []).map(r => ({
  source: r.fields.source_agent,
  category: r.fields.category,
  insight: r.fields.insight,
  confidence: r.fields.confidence
}));

// Pillar rotation
const pillars = ['AI_Builds', 'Paid_Media', 'Teaching', 'Vision', 'Trend_Commentary', 'Case_Study'];
const recentPillars = topPosts.slice(0, 7).map(p => p.pillar).filter(Boolean);
const pillarCounts = {};
pillars.forEach(p => { pillarCounts[p] = recentPillars.filter(rp => rp === p).length; });
const selectedPillar = defaults.pillar || pillars.reduce((a, b) => pillarCounts[a] <= pillarCounts[b] ? a : b);

// Format rotation
const formats = ['Story', 'Data_Insight', 'Hot_Take', 'Tutorial', 'Behind_The_Scenes', 'Thread', 'Carousel_Outline'];
const recentFormats = topPosts.slice(0, 7).map(p => p.format).filter(Boolean);
const formatCounts = {};
formats.forEach(f => { formatCounts[f] = recentFormats.filter(rf => rf === f).length; });
const selectedFormat = formats.reduce((a, b) => formatCounts[a] <= formatCounts[b] ? a : b);

return [{
  json: {
    topPosts,
    learnings,
    events,
    aiNews,
    systemLearnings,
    selectedPillar,
    selectedFormat,
    topic: defaults.topic,
    source: defaults.source,
    today: new Date().toISOString().split('T')[0]
  }
}];

const ctx = $input.first().json;

