const raw = $input.first().json;
const context = $('Build 3-Draft Prompt').first().json.context;
const text = raw.candidates[0].content.parts[0].text;
const cleaned = text.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Try extracting the outermost JSON object
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (e2) {
      // Truncated JSON - try to extract individual drafts with regex
      const draftRegex = /\{[^{}]*"draft_id"\s*:\s*"([ABC])"[^{}]*"post_text"\s*:\s*"((?:[^"\\]|\\.)*)"[^{}]*\}/g;
      const drafts = [];
      let m;
      while ((m = draftRegex.exec(cleaned)) !== null) {
        try {
          const draftObj = JSON.parse(m[0]);
          drafts.push(draftObj);
        } catch (e3) {
          drafts.push({
            draft_id: m[1],
            angle: m[1] === 'A' ? 'bold_contrarian' : m[1] === 'B' ? 'data_driven' : 'story_personal',
            post_text: m[2].replace(/\\n/g, '\n').replace(/\\"/g, '"'),
            hook_strategy: 'extracted from truncated response',
            strategy_explanation: 'extracted from truncated response'
          });
        }
      }
      if (drafts.length === 0) {
        throw new Error('Failed to parse any drafts from Gemini response: ' + cleaned.substring(0, 300));
      }
      parsed = {
        drafts: drafts,
        content_pillar: context.selectedPillar,
        post_format: context.selectedFormat,
        ai_news_used: 'unknown (truncated)',
        ecosystem_link: 'Standalone'
      };
    }
  } else {
    throw new Error('Failed to parse Gemini 3-drafts response: ' + cleaned.substring(0, 300));
  }
}

// Ensure we have at least the drafts array
const drafts = parsed.drafts || [];
if (drafts.length === 0) {
  throw new Error('No drafts found in parsed response');
}

return [{
  json: {
    drafts: drafts,
    content_pillar: parsed.content_pillar || context.selectedPillar,
    post_format: parsed.post_format || context.selectedFormat,
    ai_news_used: parsed.ai_news_used || 'none',
    ecosystem_link: parsed.ecosystem_link || 'Standalone',
    context: context
  }
}];

