const evalPrompt = 'You are a LinkedIn content quality evaluator. Score each of the following 3 draft posts for Vishant Jain's personal brand.

Vishant is the founder of Cosmisk (AI ad creation platform) and Smashed Agency (AI-powered UGC agency). His content should feel authentic, data-driven, and like a builder sharing real experiences.

Score each draft on these 5 criteria (1-10 each):

1. HOOK STRENGTH (1-10): Does the first line stop the scroll? Is it specific enough to be intriguing but not clickbait?
2. SPECIFICITY (1-10): Does it use real numbers, names, examples? Or is it generic advice anyone could write?
3. AUTHENTICITY (1-10): Does it sound like a founder sharing real experience, or like AI-generated LinkedIn content? Would you believe a human wrote this?
4. ENGAGEMENT POTENTIAL (1-10): Would people comment, share, or save this? Does it invite discussion or just broadcast?
5. BRAND ALIGNMENT (1-10): Does it naturally promote Cosmisk/Agency ecosystem without being salesy? Does it reinforce Vishant's positioning as an AI infrastructure builder?

' + draftsText + '

Return a JSON object (no markdown fences) with this exact structure:
{
  "evaluations": [
    {
      "draft_id": "A",
      "hook_strength": 8,
      "specificity": 7,
      "authenticity": 9,
      "engagement_potential": 7,
      "brand_alignment": 8,
      "total": 39,
      "strengths": "What makes this draft strong (1-2 sentences)",
      "weaknesses": "What could be improved (1-2 sentences)"
    },
    { "draft_id": "B", ... },
    { "draft_id": "C", ... }
  ],
  "best_draft_id": "A",
  "reasoning": "Why this draft is the best choice (2-3 sentences comparing them)",
  "improvement_suggestions": "If the best draft scores below 7 avg, specific suggestions for how to improve it"
}';

const geminiBody = JSON.stringify({
  systemInstruction: { parts: [{ text: 'You are a ruthlessly honest LinkedIn content evaluator. Be critical. A score of 7+ means genuinely good content that would perform well. Do not inflate scores. Generic AI-sounding content should score below 5 on authenticity.' }] },
  contents: [{ role: 'user', parts: [{ text: evalPrompt }] }],
  generationConfig: { temperature: 0.2, maxOutputTokens: 4096 }
});

return [{ json: { gemini_body: geminiBody, drafts: drafts, meta: { content_pillar: input.content_pillar, post_format: input.post_format, ai_news_used: input.ai_news_used, ecosystem_link: input.ecosystem_link }, context: input.context } }];

const raw = $input.first().json;
const prevData = $('Build Evaluation Prompt').first().json;
const drafts = prevData.drafts;
const meta = prevData.meta;
const context = prevData.context;

const text = raw.candidates[0].content.parts[0].text;
const cleaned = text.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();

let evalResult;
try {
  evalResult = JSON.parse(cleaned);
} catch (e) {
  // Try extracting individual evaluation objects with regex
  const evalRegex = /\{[^{}]*"draft_id"\s*:\s*"([A-C])"[^{}]*"hook_strength"\s*:\s*(\d+)[^{}]*"specificity"\s*:\s*(\d+)[^{}]*"authenticity"\s*:\s*(\d+)[^{}]*"engagement_potential"\s*:\s*(\d+)[^{}]*"brand_alignment"\s*:\s*(\d+)[^{}]*/g;
  const evals = [];
  let m;
  while ((m = evalRegex.exec(cleaned)) !== null) {
    evals.push({
      draft_id: m[1],
      hook_strength: parseInt(m[2]),
      specificity: parseInt(m[3]),
      authenticity: parseInt(m[4]),
      engagement_potential: parseInt(m[5]),
      brand_alignment: parseInt(m[6]),
      strengths: '',
      weaknesses: ''
    });
  }
  if (evals.length > 0) {
    const bestMatch = cleaned.match(/"best_draft_id"\s*:\s*"([A-C])"/);
    const reasonMatch = cleaned.match(/"reasoning"\s*:\s*"((?:[^"\\\\]|\\\\.)*)"/);
    evalResult = {
      evaluations: evals,
      best_draft_id: bestMatch ? bestMatch[1] : evals[0].draft_id,
      reasoning: reasonMatch ? reasonMatch[1] : 'Extracted from truncated response',
      improvement_suggestions: ''
    };
  } else {
    throw new Error('Failed to parse evaluation response: ' + cleaned.substring(0, 300));
  }
}

const evaluations = evalResult.evaluations || [];

// Calculate totals and find best
let bestEval = null;
let bestTotal = 0;
for (const ev of evaluations) {
  ev.total = (ev.hook_strength || 0) + (ev.specificity || 0) + (ev.authenticity || 0) + (ev.engagement_potential || 0) + (ev.brand_alignment || 0);
  if (ev.total > bestTotal) {
    bestTotal = ev.total;
    bestEval = ev;
  }
}

if (!bestEval) {
  throw new Error('No evaluations found');
}

// Find the matching draft
const bestDraft = drafts.find(d => d.draft_id === bestEval.draft_id) || drafts[0];

const avgScore = bestTotal / 5;
const needsRetry = avgScore < 7;

let retryFeedback = '';
if (needsRetry) {
  // Build specific feedback about what was weak
  const weakAreas = [];
  if (bestEval.hook_strength < 7) weakAreas.push('Hook needs to be more specific and scroll-stopping (scored ' + bestEval.hook_strength + '/10)');
  if (bestEval.specificity < 7) weakAreas.push('Too generic - needs real numbers, specific examples, concrete details (scored ' + bestEval.specificity + '/10)');
  if (bestEval.authenticity < 7) weakAreas.push('Sounds too AI-generated - needs more personal voice, imperfections, real founder energy (scored ' + bestEval.authenticity + '/10)');
  if (bestEval.engagement_potential < 7) weakAreas.push('Low engagement potential - needs a stronger CTA, controversial take, or question that invites debate (scored ' + bestEval.engagement_potential + '/10)');
  if (bestEval.brand_alignment < 7) weakAreas.push('Brand alignment weak - needs to more naturally reference Cosmisk/Agency ecosystem (scored ' + bestEval.brand_alignment + '/10)');
  retryFeedback = weakAreas.join('. ') + '. Evaluator said: ' + (bestEval.weaknesses || '') + '. ' + (evalResult.improvement_suggestions || '');
}

return [{
  json: {
    selected_draft: bestDraft,
    scores: bestEval,
    all_evaluations: evaluations,
    reasoning: evalResult.reasoning || '',
    needs_retry: needsRetry,
    retry_feedback: retryFeedback,
    total_score: bestTotal,
    avg_score: avgScore,
    meta: meta,
    context: context
  }
}];

