const scoresJson = JSON.stringify({ hook_strength: scores.hook_strength, specificity: scores.specificity, authenticity: scores.authenticity, engagement_potential: scores.engagement_potential, brand_alignment: scores.brand_alignment, total: scores.total, avg: (scores.total / 5).toFixed(1), retried: true, changes_made: parsed.changes_made || '' });

const airtableFields = {
  post_date: today,
  content_pillar: meta.content_pillar,
  post_format: meta.post_format,
  draft_text: parsed.post_text,
  status: 'draft',
