  ai_news_source: meta.ai_news_used || '',
  ecosystem_link: meta.ecosystem_link || 'Standalone',
  created_at: new Date().toISOString()
};

return [{
  json: {
    slack_message: slackMessage,
    airtable_fields: airtableFields,
    post_text: parsed.post_text,
    scores: scores,
    meta: meta,
    retried: true
  }
