if (postedWithEngagement.length === 0) {
  return [{ json: { has_data: false, gemini_body: '', posts_summary: 'No posted records with engagement data this week.' } }];
}

const postsSummary = postedWithEngagement.map((r, i) => {
  const f = r.fields;
  return 'Post ' + (i + 1) + ':
  Pillar: ' + (f.content_pillar || 'unknown') + '
  Format: ' + (f.post_format || 'unknown') + '
  Likes: ' + (f.likes || 0) + '
  Comments: ' + (f.comments_count || 0) + '
  Impressions: ' + (f.impressions || 0) + '
  Hook: ' + (f.strategy_used || 'unknown') + '
  Text: ' + ((f.draft_text || '').substring(0, 300));
}).join('

');

const prompt = 'Analyze the following LinkedIn post performance data for Vishant Jain's personal brand account. Identify patterns, what worked, what didn't, and extract actionable learnings.

