// Read the Gemini analysis from Parse & Build Learnings
const parseData = $('Parse & Build Learnings').first().json;
const analysis = parseData.gemini_analysis;

if (!analysis || !analysis.learnings || analysis.learnings.length === 0) {
  return [{ json: { learningsCount: 0, airtable_body: '' } }];
}

const today = new Date().toISOString().split('T')[0];
const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
const dateRange = weekAgo + ' to ' + today;

// Filter for cross-cutting insights useful to OTHER agents
const crossCuttingCategories = {
  'hook_patterns': 'hook_patterns',
  'audience_engagement': 'audience_insight',
  'topic_resonance': 'audience_insight',
  'content_pillars': 'content_format',
  'format_performance': 'content_format',
  'posting_time': 'timing_pattern'
};

// Extract 1-3 learnings that generalize beyond LinkedIn
const sysLearnings = [];

for (const l of analysis.learnings) {
  if (sysLearnings.length >= 3) break;

  const insight = (l.insight || '').toLowerCase();
  const title = (l.title || '').toLowerCase();

  // Check if this insight generalizes beyond LinkedIn-specific tactics
  const isCrossCutting =
    // Hook/attention patterns useful for Script Agent
    insight.includes('hook') || insight.includes('scroll') || insight.includes('attention') ||
    insight.includes('save') || insight.includes('share') ||
    // Audience/topic insights useful for Outreach or Content Strategy
    insight.includes('audience') || insight.includes('resonate') || insight.includes('topic') ||
    insight.includes('industry') || insight.includes('persona') || insight.includes('targeting') ||
    // Content format insights useful broadly
    insight.includes('contrarian') || insight.includes('data') || insight.includes('story') ||
    insight.includes('specific') || insight.includes('number') || insight.includes('metric') ||
    // Engagement patterns
    insight.includes('comment') || insight.includes('engage') || insight.includes('cta');

  if (isCrossCutting) {
    const category = crossCuttingCategories[l.category] || 'content_format';
    const confidence = l.evidence && l.evidence.length > 20 ? 0.7 : 0.5;

    sysLearnings.push({
      fields: {
        title: l.title,
        source_agent: 'linkedin_brand',
        category: category,
        insight: l.insight,
        evidence: 'LinkedIn weekly review \u2014 ' + dateRange + '. ' + (l.evidence || ''),
        confidence: confidence,
        active: true,
        created_at: new Date().toISOString()
      }
    });
  }
}

if (sysLearnings.length === 0) {
  return [{ json: { learningsCount: 0, airtable_body: '' } }];
}

const airtableBody = JSON.stringify({ records: sysLearnings });

return [{ json: { learningsCount: sysLearnings.length, airtable_body: airtableBody } }];
